const input = $json || {};
if (input.ok !== true || input.due !== true || input.event !== 'reservation.reminder') return [];
const positive = (value) => Number.isInteger(Number(value)) && Number(value) > 0;
const valid = (n) => { const c = n && n.contact || {}; const r = n && n.reservation || {}; const d = n && n.data || {}; const contact = c.type === 'email' ? /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(c.value || '')) : c.type === 'whatsapp' ? /^\+52\d{10}$/.test(String(c.value || '')) : false; return n && Number(n.schema_version) === 1 && n.event === 'reservation.reminder' && positive(n.source_id) && positive(n.reservation_id) && Number(n.attempt) === 1 && contact && n.recipient && String(n.recipient.name || '').trim() !== '' && /^\d{4}-\d{2}-\d{2}$/.test(String(r.date || '')) && /^\d{2}:\d{2}$/.test(String(r.time || '')) && positive(r.guests) && /^https?:\/\/[^\s]+$/i.test(String(d.management_url || '')) && !Number.isNaN(Date.parse(String(d.access_expires_at || ''))); };
return (Array.isArray(input.notifications) ? input.notifications : []).filter(valid).map((notification) => ({ json: notification }));

const n = $json;
const r = n.reservation;
const d = n.data;
const values = [n.recipient.name, r.date, r.time, r.guests, d.management_url];
return { json: { ...n, email_subject: 'Tu reservación es mañana', email_text: `Hola ${n.recipient.name},

Te esperamos mañana en Casa Pestalozzi.

${r.date} a las ${r.time} · ${r.guests} personas

Puedes revisar, modificar o cancelar tu reservación aquí:
${d.management_url}

Este acceso vence el ${d.access_expires_at}.`, whatsapp_template: 'reservation_reminder', whatsapp_components: { component: [{ type: 'body', bodyParameters: { parameter: values.map((value) => ({ type: 'text', text: String(value) })) } }] } } };

const n = $json || {};
const contact = n.contact || {};
const data = n.data || {};
if (contact.type !== 'email') return [];
return { json: { schema_version: n.schema_version, event: n.event, source_id: n.source_id, reservation_id: n.reservation_id, attempt: n.attempt, channel: 'email', to: String(contact.value || ''), subject: String(n.email_subject || ''), message: String(n.email_text || ''), purpose: String(data.purpose || '') } };

const n = $json || {};
const contact = n.contact || {};
const data = n.data || {};
if (contact.type !== 'whatsapp') return [];
return { json: { schema_version: n.schema_version, event: n.event, source_id: n.source_id, reservation_id: n.reservation_id, attempt: n.attempt, channel: 'whatsapp', to: String(contact.value || ''), template: String(n.whatsapp_template || ''), components: n.whatsapp_components || {}, purpose: String(data.purpose || '') } };
